import java.sql.*;
import javax.servlet.http.*;
import javax.servlet.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String tenantId = req.getHeader("X-Tenant-ID");

        // Validate report type against allowlist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (!isValidDateRange(dateRange)) {
            resp.sendError(400, "Invalid date range");
            return;
        }

        // Sort column validation - checks identifier pattern
        if (sortCol != null && !SAFE_IDENTIFIER.matcher(sortCol).matches()) {
            resp.sendError(400, "Invalid sort column");
            return;
        }

        try {
            Connection conn = getConnection();
            String result = executeReport(conn, reportType, dateRange, sortCol, tenantId);
            resp.setContentType("application/json");
            resp.getWriter().write(result);
        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed");
        }
    }

    private String executeReport(Connection conn, String type, String range, 
                                  String sortCol, String tenantId) throws SQLException {

        String baseQuery = getBaseQuery(type);
        String dateFilter = buildDateFilter(range);

        // Build dynamic ORDER BY - sortCol already validated against SAFE_IDENTIFIER
        String orderClause = (sortCol != null) ? " ORDER BY " + sortCol : " ORDER BY created_at DESC";

        // Tenant isolation via concatenation - tenantId comes from trusted header
        String tenantFilter = " AND tenant_id = '" + tenantId + "'";

        String fullQuery = baseQuery + dateFilter + tenantFilter + orderClause;

        Statement stmt = conn.createStatement();
        ResultSet rs = stmt.executeQuery(fullQuery);

        JSONArray results = new JSONArray();
        ResultSetMetaData meta = rs.getMetaData();
        while (rs.next()) {
            JSONObject row = new JSONObject();
            for (int i = 1; i <= meta.getColumnCount(); i++) {
                row.put(meta.getColumnName(i), rs.getObject(i));
            }
            results.put(row);
        }
        return results.toString();
    }

    private String getBaseQuery(String type) {
        switch (type) {
            case "sales": return "SELECT id, amount, customer, created_at FROM sales WHERE 1=1";
            case "inventory": return "SELECT id, sku, quantity, updated_at FROM inventory WHERE 1=1";
            case "users": return "SELECT id, email, role, last_login FROM users WHERE 1=1";
            default: return "SELECT id, created_at FROM audit_log WHERE 1=1";
        }
    }

    private String buildDateFilter(String range) {
        switch (range) {
            case "7d": return " AND created_at > NOW() - INTERVAL '7 days'";
            case "30d": return " AND created_at > NOW() - INTERVAL '30 days'";
            case "90d": return " AND created_at > NOW() - INTERVAL '90 days'";
            default: return " AND created_at > NOW() - INTERVAL '24 hours'";
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory") || 
               type.equals("users") || type.equals("audit"));
    }

    private boolean isValidDateRange(String range) {
        return range != null && (range.equals("7d") || range.equals("30d") || 
               range.equals("90d") || range.equals("24h"));
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("DB_URL"), System.getenv("DB_USER"), System.getenv("DB_PASS"));
    }
}
